<template>
	<view class="follow-page">
		<view class="fixed-header" :style="{ paddingTop: statusBarHeight + 'px' }">
			<view class="nav-bar">
				<view class="back-btn" @click="goBack">‹</view>
				<text class="nav-title">{{ pageTitle }}</text>
				<view class="placeholder"></view>
			</view>
			<view class="segment">
				<view class="segment-item" :class="{ active: activeTab === 'following' }" @click="switchTab('following')">关注</view>
				<view class="segment-item" :class="{ active: activeTab === 'followers' }" @click="switchTab('followers')">粉丝</view>
			</view>
		</view>

		<scroll-view class="follow-scroll" scroll-y enhanced :show-scrollbar="false" :style="{ paddingTop: headerHeight + 'px' }">
			<view class="user-list">
				<view v-if="loading" class="empty-state">正在加载</view>
				<view v-else-if="!filteredUsers.length" class="empty-state">{{ activeTab === 'following' ? '还没有关注的人' : '还没有粉丝' }}</view>
				<view v-for="item in filteredUsers" :key="item.id" class="user-row" @click="goUser(item.id)">
					<image class="avatar" :src="item.avatar" mode="aspectFill" />
					<view class="user-main">
						<VipName class="name" :name="item.name" :is-member="item.isMember" />
						<text class="bio">{{ item.bio }}</text>
					</view>
					<view v-if="item.id !== currentUserId" class="action" :class="{ followed: item.followed }" @click.stop="handleFollowAction(item)">
						{{ item.followed ? '已关注' : '关注' }}
					</view>
				</view>
			</view>
		</scroll-view>
	</view>
</template>

<script>
import { DEFAULT_AVATAR_URL } from '../../config';
import { fetchFollowers, fetchFollowing, followUser, unfollowUser } from '../../api/follow';
import { showRequestError } from '../../utils/feedback';
import { getCurrentUser } from '../../utils/auth';
import * as profileGuard from '../../utils/profileGuard';
import VipName from '../../components/VipName.vue';

export default {
	components: { VipName },
	data() {
		return {
			statusBarHeight: 44,
			headerHeight: 154,
			activeTab: 'following',
			targetUserId: 'me',
			targetName: '',
			currentUserId: '',
			loading: false,
			users: {
				following: [],
				followers: []
			}
		};
	},
	computed: {
		filteredUsers() {
			return this.users[this.activeTab] || [];
		},
		pageTitle() {
			if (!this.targetName) return '关注关系';
			return this.activeTab === 'followers' ? `${this.targetName}的粉丝` : `${this.targetName}的关注`;
		}
	},
	onLoad(query) {
		if (query && ['following', 'followers'].includes(query.tab)) this.activeTab = query.tab;
		if (query && query.id) this.targetUserId = decodeURIComponent(query.id);
		if (query && query.name) this.targetName = decodeURIComponent(query.name);
		const currentUser = getCurrentUser() || {};
		this.currentUserId = currentUser.id || currentUser.userId || '';
		this.setHeaderHeight();
	},
	onShow() {
		this.loadList();
	},
	methods: {
		setHeaderHeight() {
			try {
				const info = uni.getSystemInfoSync();
				this.statusBarHeight = info.statusBarHeight || 44;
				const rpxToPx = (info.windowWidth || 375) / 750;
				this.headerHeight = this.statusBarHeight + Math.round(164 * rpxToPx);
			} catch (error) {
				this.headerHeight = 154;
			}
		},
		switchTab(tab) {
			if (this.activeTab === tab) return;
			this.activeTab = tab;
			this.loadList();
		},
		normalizeUser(item = {}) {
			return {
				id: item.id || '',
				name: item.name || item.nickname || item.stampNo || '同频旅人',
				avatar: item.avatar || item.avatarUrl || DEFAULT_AVATAR_URL,
				bio: item.bio || item.intro || '还没写个人介绍',
				followed: Boolean(item.followed),
				isMember: Boolean(item.isMember)
			};
		},
		async loadList() {
			this.loading = true;
			try {
				const targetId = this.targetUserId || 'me';
				const result = this.activeTab === 'followers'
					? await fetchFollowers(targetId)
					: await fetchFollowing(targetId);
				const items = Array.isArray(result && result.items) ? result.items : [];
				this.users = {
					...this.users,
					[this.activeTab]: items.map(this.normalizeUser)
				};
			} catch (error) {
				showRequestError(error, '关注关系加载失败');
			} finally {
				this.loading = false;
			}
		},
		async goUser(id) {
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '查看主页' }))) return;
			uni.navigateTo({ url: `/pages/user/index?id=${id}` });
		},
		async handleFollowAction(item) {
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '关注' }))) return;
			const previousFollowed = item.followed;
			item.followed = !item.followed;
			const actionText = item.followed ? '关注' : '取关';
			try {
				if (item.followed) {
					await followUser(item.id);
					this.showToast('已关注');
				} else {
					await unfollowUser(item.id);
					this.showToast('已取关');
					if (this.activeTab === 'following') {
						this.users = {
							...this.users,
							following: this.users.following.filter((user) => user.id !== item.id)
						};
					}
				}
			} catch (error) {
				item.followed = previousFollowed;
				showRequestError(error, `${actionText}失败`);
			}
		},
		showToast(title) {
			uni.showToast({ title, icon: 'none' });
		},
		goBack() {
			uni.navigateBack();
		}
	}
};
</script>

<style lang="scss" scoped>
.follow-page {
	min-height: 100vh;
	background: #f7f3f6;
}

.fixed-header {
	position: fixed;
	top: 0;
	left: 0;
	right: 0;
	z-index: 10;
	background: rgba(255, 255, 255, 0.97);
	border-bottom: 1rpx solid #f0e5ea;
}

.nav-bar {
	position: relative;
	display: flex;
	align-items: center;
	justify-content: space-between;
	height: 96rpx;
	padding: 0 28rpx;
}

.back-btn,
.placeholder {
	width: 72rpx;
	height: 72rpx;
}

.back-btn {
	display: flex;
	align-items: center;
	justify-content: center;
	font-size: 52rpx;
	color: #33262e;
}

.nav-title {
	position: absolute;
	left: 150rpx;
	right: 150rpx;
	text-align: center;
	font-size: 32rpx;
	font-weight: 700;
	color: #221820;
}

.segment {
	display: flex;
	gap: 12rpx;
	padding: 0 24rpx 22rpx;
}

.segment-item {
	flex: 1;
	display: flex;
	align-items: center;
	justify-content: center;
	height: 60rpx;
	border-radius: 999rpx;
	background: #f6f1f4;
	color: #766870;
	font-size: 24rpx;
}

.segment-item.active {
	background: #221820;
	color: #ffffff;
	font-weight: 700;
}

.follow-scroll {
	height: 100vh;
}

.user-list {
	padding: 24rpx;
}

.empty-state {
	display: flex;
	align-items: center;
	justify-content: center;
	min-height: 260rpx;
	color: #9c8c95;
	font-size: 25rpx;
}

.user-row {
	display: flex;
	align-items: center;
	gap: 18rpx;
	padding: 24rpx;
	border-radius: 24rpx;
	background: #ffffff;
	box-shadow: 0 10rpx 28rpx rgba(90, 55, 76, 0.05);
}

.user-row + .user-row {
	margin-top: 16rpx;
}

.avatar {
	width: 78rpx;
	height: 78rpx;
	border-radius: 50%;
	background: #f0edf0;
}

.user-main {
	flex: 1;
	min-width: 0;
}

.name,
.bio {
	display: block;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.name {
	font-size: 28rpx;
	font-weight: 800;
	color: #241b22;
}

.bio {
	margin-top: 8rpx;
	font-size: 23rpx;
	color: #9c8c95;
}

.action {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 116rpx;
	height: 58rpx;
	border-radius: 999rpx;
	background: #221820;
	color: #ffffff;
	font-size: 23rpx;
	font-weight: 700;
}

.action.followed {
	background: #f6f1f4;
	color: #766870;
}
</style>
